function update(){const faces=Array.from(document.fonts).map(f=>({family:f.family,weight:f.weight,status:f.status}));const resources=performance.getEntriesByType('resource').filter(r=>/\.(woff2?|ttf|otf)(?:\?|$)/.test(r.name)).map(r=>({url:r.name.split('/').slice(-2).join('/'),bytes:r.decodedBodySize,transfer:r.transferSize,durationMs:Math.round(r.duration)}));const probes=[['Bricolage Grotesque','FinModel Lab',600],['Glow Sans SC','均值方差投资组合解释风险收益',400],['Monaspace Argon','x <- c(1, 2, 3); A %*% B; x != 0',400],['Monaspace Neon','0123456789.65%',500],['KaTeX_Main','123=()',400],['KaTeX_Math','xy',400]];const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');function pixels(family,text,weight){canvas.width=900;canvas.height=90;ctx.clearRect(0,0,900,90);ctx.font=`${family.includes('KaTeX_Math')?'italic ':''}${weight} 48px ${family}`;ctx.fillText(text,4,60);let hash=2166136261;for(const x of ctx.getImageData(0,0,900,90).data)hash=Math.imul(hash^x,16777619);return hash>>>0;}const metrics=probes.map(([family,text,weight])=>{ctx.font=`${weight} 48px "${family}", monospace`;const customWidth=ctx.measureText(text).width;ctx.font=`${weight} 48px monospace`;const fallbackWidth=ctx.measureText(text).width;return{family,text,weight,registered:faces.some(f=>f.family.replaceAll('"','')===family),ready:document.fonts.check(`${family==='KaTeX_Math'?'italic ':''}${weight} 16px "${family}"`,text),customWidth,fallbackWidth,differentFromFallback:Math.abs(customWidth-fallbackWidth)>.01,pixelHash:pixels('\"'+family+'\", monospace',text,weight),fallbackPixelHash:pixels('monospace',text,weight)};});const nav=performance.getEntriesByType('navigation')[0];output.textContent=JSON.stringify({atMs:Math.round(performance.now()),faces,resources,fontBytes:resources.reduce((a,r)=>a+r.bytes,0),fontRequestCount:resources.length,paint:performance.getEntriesByType('paint').map(x=>({name:x.name,ms:Math.round(x.startTime)})),domContentLoadedMs:nav?Math.round(nav.domContentLoadedEventEnd):null,cls,metrics});}
